<?php
declare(strict_types=1);namespace App\Service;use App\Exception\AuthException;use Hyperf\DbConnection\Db;
final class GatewayAccessService{public function __construct(private Db$db){} /** @return array<string,mixed> */public function resolve(string$key,int$subscriptionId):array{if(!preg_match('/^app_live_(ak_[a-f0-9]{12})\.[a-f0-9]{64}$/D',$key,$m))throw AuthException::invalidCredentials();$row=$this->db->selectOne('SELECT c.`secret_hash`,s.`id` AS `subscription_id`,s.`api_version_id`,q.`qps_limit`,q.`period_limit`,q.`period_seconds` FROM `application_credentials` c INNER JOIN `buyer_applications` a ON a.`id`=c.`application_id` INNER JOIN `api_subscriptions` s ON s.`application_id`=a.`id` INNER JOIN `subscription_quotas` q ON q.`subscription_id`=s.`id` AND q.`deleted_at` IS NULL WHERE c.`key_prefix`=? AND s.`id`=? AND c.`status`=\'active\' AND s.`status`=\'active\' AND a.`status`=\'active\' AND c.`deleted_at` IS NULL AND s.`deleted_at` IS NULL LIMIT 1',[$m[1],$subscriptionId]);if(!is_object($row)||!hash_equals((string)$row->secret_hash,hash('sha256',$key)))throw AuthException::invalidCredentials();return get_object_vars($row);}}
